<?php
declare(strict_types=1);

/*
 * RouteGuard 1.1.0: однофайловое обновление «Помощник звонка».
 * Файл не зависит от базы данных и может быть запущен до или после install.php.
 */
header('Content-Type: text/plain; charset=utf-8');

$root = realpath(dirname(__DIR__));
if ($root === false) {
    http_response_code(500);
    exit("ERROR: не найден корень приложения.\n");
}
$configPath = $root . DIRECTORY_SEPARATOR . 'config.php';
if (!is_file($configPath)) {
    http_response_code(500);
    exit("ERROR: не найден config.php.\n");
}
$config = require $configPath;
$expected = (string)($config['maintenance_token'] ?? '');
$provided = (string)($_GET['token'] ?? ($_SERVER['HTTP_X_MAINTENANCE_TOKEN'] ?? ''));
if (PHP_SAPI !== 'cli' && (strlen($expected) < 24 || !hash_equals($expected, $provided))) {
    http_response_code(403);
    exit("Доступ запрещён. Укажите maintenance_token.\n");
}

$version = '1.1.0-call-assistant';
$marker = __DIR__ . DIRECTORY_SEPARATOR . '.applied-' . $version;
$allowed = [
    'app/CallAssistant.php',
    'app/bootstrap.php',
    'api.php',
    'index.php',
    'assets/app.js',
    'assets/app.css',
];
$encoded = '';
$decoded = base64_decode($encoded, true);
if ($decoded === false || !function_exists('gzdecode')) {
    http_response_code(500);
    exit("ERROR: сервер не смог распаковать обновление (нужен PHP zlib).\n");
}
$json = gzdecode($decoded);
$files = $json === false ? null : json_decode($json, true);
if (!is_array($files) || array_keys($files) !== $allowed) {
    http_response_code(500);
    exit("ERROR: пакет обновления повреждён.\n");
}

$alreadyCurrent = is_file($marker);
if ($alreadyCurrent) {
    foreach ($files as $relative => $contents) {
        $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
        if (!is_file($target) || !hash_equals(hash('sha256', (string)$contents), hash_file('sha256', $target))) {
            $alreadyCurrent = false;
            break;
        }
    }
}
if ($alreadyCurrent) {
    exit("SKIP {$version}: обновление уже установлено.\n");
}

$backupRoot = __DIR__ . DIRECTORY_SEPARATOR . 'backups';
if (!is_dir($backupRoot) && !mkdir($backupRoot, 0750, true) && !is_dir($backupRoot)) {
    http_response_code(500);
    exit("ERROR: не удалось создать каталог резервных копий.\n");
}
file_put_contents($backupRoot . DIRECTORY_SEPARATOR . '.htaccess', "Require all denied\nDeny from all\n", LOCK_EX);
$backupDir = $backupRoot . DIRECTORY_SEPARATOR . date('Ymd-His');
if (!mkdir($backupDir, 0750, true) && !is_dir($backupDir)) {
    http_response_code(500);
    exit("ERROR: не удалось создать резервную копию.\n");
}

$staged = [];
try {
    foreach ($files as $relative => $contents) {
        if (!in_array($relative, $allowed, true) || str_contains($relative, '..')) {
            throw new RuntimeException('Недопустимый путь: ' . $relative);
        }
        $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
        $targetDir = dirname($target);
        if (!is_dir($targetDir) && !mkdir($targetDir, 0755, true) && !is_dir($targetDir)) {
            throw new RuntimeException('Не удалось создать каталог: ' . $relative);
        }
        if (is_file($target)) {
            $backup = $backupDir . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $relative);
            if (!is_dir(dirname($backup)) && !mkdir(dirname($backup), 0750, true) && !is_dir(dirname($backup))) {
                throw new RuntimeException('Не удалось создать каталог резервной копии.');
            }
            if (!copy($target, $backup)) {
                throw new RuntimeException('Не удалось сохранить резервную копию: ' . $relative);
            }
        }
        $temporary = $target . '.routeguard-new';
        if (file_put_contents($temporary, (string)$contents, LOCK_EX) === false) {
            throw new RuntimeException('Не удалось подготовить файл: ' . $relative);
        }
        if (!hash_equals(hash('sha256', (string)$contents), hash_file('sha256', $temporary))) {
            throw new RuntimeException('Контрольная сумма не совпала: ' . $relative);
        }
        $staged[$relative] = [$temporary, $target];
    }

    foreach ($staged as $relative => [$temporary, $target]) {
        if (!copy($temporary, $target)) {
            throw new RuntimeException('Не удалось заменить файл: ' . $relative);
        }
        unlink($temporary);
        echo "OK {$relative}\n";
    }
    file_put_contents($marker, date(DATE_ATOM) . "\n", LOCK_EX);
    echo "OK {$version}\n";
    echo "Помощник звонка установлен. Резервные копии: FIX/backups/" . basename($backupDir) . "\n";
} catch (Throwable $error) {
    foreach ($staged as [$temporary]) {
        if (is_file($temporary)) @unlink($temporary);
    }
    http_response_code(500);
    echo "ERROR {$version}: {$error->getMessage()}\n";
    echo "Исходные файлы сохранены в FIX/backups/" . basename($backupDir) . "\n";
}
